 @SuppressWarnings("unchecked") public double[] weights(double[] prior){Map<String,Object> f=budgetFrame();if(f==null)return prior;double[] raw=MutationOpsR27.defaultWeights();List<Object> evidence=new ArrayList<>();Set<String> creditedR31=new HashSet<>();for(Object o:(List<?>)f.get("points")){Map<String,Object> p=(Map<String,Object>)o;Object lower=p.get("lower"),upper=p.get("upper");if(!(lower instanceof Number)||!(upper instanceof Number))continue;String op=String.valueOf(p.get("operator"));
  // R31-B07-C03#A2: one paired parent/child experiment credits its operator once, however many receipts repeat it.
  String experimentR31=op+"|"+p.get("parentHash")+"|"+(p.get("childHash")!=null?p.get("childHash"):JsonR27.write(p));if(!creditedR31.add(experimentR31))continue;for(int i=0;i<MutationOpsR27.OPS.length;i++)if(op.equals(MutationOpsR27.OPS[i])){double l=((Number)lower).doubleValue(),u=((Number)upper).doubleValue();if(l>0)raw[i]*=1+Math.min(2,l*10);else if(u<0)raw[i]*=.5;else continue;evidence.add(p);}}if(evidence.isEmpty())return prior;double sum=0;for(double w:raw)sum+=Math.max(.001,w);double[] result=new double[raw.length];for(int i=0;i<result.length;i++)result[i]=.25/result.length+.75*Math.max(.001,raw[i])/sum;budgetReceipt=new LinkedHashMap<>();budgetReceipt.put("version","RESEARCH_PAIRED_BUDGET1");budgetReceipt.put("role","SELECT");budgetReceipt.put("sourceRun",budgetRun());budgetReceipt.put("beforeWeights",prior.clone());budgetReceipt.put("afterWeights",result.clone());budgetReceipt.put("explorationMass",.25);budgetReceipt.put("evidence",evidence);budgetReceipt.put("permanentFamilyDeletion",false);return result;}
 @SuppressWarnings("unchecked") public int familyCredit(String family){Map<String,Object> f=budgetFrame();if(f==null)return 0;Set<String> identities=new HashSet<>();for(Object o:(List<?>)f.get("points")){Map<String,Object> p=(Map<String,Object>)o;if(family.equals(p.get("family"))&&p.get("lower") instanceof Number&&((Number)p.get("lower")).doubleValue()>0)identities.add(String.valueOf(p.get("childHash")));}return identities.size();}
 public void appendBudgetReceipt(ResearchWriteQueueR27.Batch b,int generation,long from,long through){if(budgetReceipt==null)return;String run=(String)budgetReceipt.get("sourceRun");b.guardBefore(db->{ResearchInputPinR30R1.require(db,datasetHash,revision);return 0;});b.add("INSERT OR IGNORE INTO r30r1_research_measure VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",run,"BUDGET_APPLIED_GENERATION:"+generation,"RESEARCH_BUDGET",StatsR27.sha256("ORIGINAL_EVOLUTION_BUDGET"),"ORIGINAL_EVOLUTION_CURSOR_SAME_TRANSACTION",from,through,0,null,null,null,JsonR27.write(budgetReceipt));}
 @SuppressWarnings("unchecked") public PolicySpecR27 measuredPrune(PolicySpecR27 parent,int generation){Map<String,Object> matrix=frames.get("MATRIX:COUNTER_EVIDENCE");if(matrix==null||!(matrix.get("details") instanceof Map))return null;Object receipts=((Map<?,?>)matrix.get("details")).get("sourceReceipts");if(!(receipts instanceof List))return null;for(Object o:(List<?>)receipts){Map<String,Object> p=(Map<String,Object>)o;if(!(p.get("parent") instanceof String)||!(p.get("upper95") instanceof Number)||((Number)p.get("upper95")).doubleValue()>=0)continue;PolicySpecR27 measuredParent=PolicySpecR27.parse((String)p.get("parent"));if(!parent.policyHash().equals(measuredParent.policyHash()))continue;PolicySpecR27 child=DirectedResearchPolicyR30R1.withoutChild(parent,(String)p.get("componentPath"),generation);if(!child.policyHash().equals(p.get("counterfactualHash")))throw new IllegalStateException("COUNTER_MATRIX_CHILD_SUBSTITUTION");Map<String,Object> causal=frames.get("MATRIX:CAUSAL_SUPPORT");if(causal!=null){int row=axis(causal,"rows").indexOf(parent.policyHash()+":"+p.get("componentPath"));if(row>=0){if(cell(causal,row,0)!=1||cell(causal,row,1)!=1||cell(causal,row,2)<4)return null;use("MATRIX:CAUSAL_SUPPORT");}}use("MATRIX:COUNTER_EVIDENCE");if(p.get("sourceRun") instanceof String)used.add(ResearchContractR30R1.sha((String)p.get("sourceRun")));return annotate(child);}return null;}
 @SuppressWarnings("unchecked") private List<?> axis(Map<String,Object> m,String key){Object x=m.get(key);return x instanceof List?(List<?>)x:Collections.emptyList();}
 @SuppressWarnings("unchecked") private Map<String,Object> details(Map<String,Object> m){Object x=m.get("details");return x instanceof Map?(Map<String,Object>)x:Collections.emptyMap();}
 private double cell(Map<String,Object> m,int row,int column){List<?> rows=axis(m,"values");if(row<0||row>=rows.size())return Double.NaN;List<?> values=(List<?>)rows.get(row);if(column<0||column>=values.size()||!(values.get(column) instanceof Number))return Double.NaN;return ((Number)values.get(column)).doubleValue();}
 private long support(Map<String,Object> m,int row,int column){List<?> rows=axis(m,"support");if(row<0||row>=rows.size())return 0;List<?> values=(List<?>)rows.get(row);return column>=0&&column<values.size()&&values.get(column) instanceof Number?((Number)values.get(column)).longValue():0;}
 public int position(StatsR27.SplitMix r,int fallback){Map<String,Object> m=frames.get("MATRIX:NUMBER_POSITION_COMPATIBILITY");if(m==null||r.chance(.25))return fallback;double best=-1;List<Integer> positions=new ArrayList<>();for(int p=0;p<10;p++){double deviation=0;boolean known=true;for(int k=0;k<10;k++){double value=cell(m,k,p);if(!Double.isFinite(value)||support(m,k,p)<200){known=false;break;}deviation+=(value-.1)*(value-.1);}if(known){if(deviation>best+1e-12){positions.clear();best=deviation;}if(Math.abs(deviation-best)<1e-12)positions.add(p+1);}}if(positions.isEmpty()||best<=1e-12)return fallback;/* R31-B08-C04: a flat (no-signal) frame is no product, not a random consumption */use("MATRIX:NUMBER_POSITION_COMPATIBILITY");return positions.get(r.nextInt(positions.size()));}
 public List<PolicySpecR27> fusionParents(List<PolicySpecR27> archive,StatsR27.SplitMix r){String kind=frames.containsKey("MATRIX:ALGORITHM_COMPLEMENTARITY")&&(!frames.containsKey("MATRIX:TEACHER_DIVERSITY")||r.chance(.5))?"MATRIX:ALGORITHM_COMPLEMENTARITY":"MATRIX:TEACHER_DIVERSITY";Map<String,Object> m=frames.get(kind);if(m==null||r.chance(.25))return archive;Map<String,PolicySpecR27> policies=new HashMap<>();for(PolicySpecR27 p:archive)policies.put(p.policyHash(),p);List<?> rows=axis(m,"rows"),cols=axis(m,"columns");List<List<PolicySpecR27>> eligible=new ArrayList<>();for(int i=0;i<rows.size();i++)for(int j=0;j<cols.size();j++){if(i==j)continue;double correlation=cell(m,i,j);PolicySpecR27 a=policies.get(String.valueOf(rows.get(i))),b=policies.get(String.valueOf(cols.get(j)));if(a!=null&&b!=null&&a.position==b.position&&support(m,i,j)>=200&&Double.isFinite(correlation)&&(kind.equals("MATRIX:TEACHER_DIVERSITY")?correlation>.01:correlation>.2))eligible.add(Arrays.asList(a,b));}if(eligible.isEmpty())return archive;use(kind);return eligible.get(r.nextInt(eligible.size()));}
 public PolicySpecR27 premiseHypothesis(IdeaFamilyR27.Context ctx,StatsR27.SplitMix r){if(r.chance(.25))return null;String source=frames.containsKey("MATRIX:FORWARD_REASONING")?"MATRIX:FORWARD_REASONING":"MATRIX:EVIDENCE_TEACHER";Map<String,Object> m=frames.get(source);if(m==null)return null;Object programs=details(m).get(source.equals("MATRIX:FORWARD_REASONING")?"programsAndPremises":"teacherPrograms");if(!(programs instanceof List)||((List<?>)programs).isEmpty())return null;int index=r.nextInt(((List<?>)programs).size());PolicySpecR27 base=PolicySpecR27.parse(String.valueOf(((List<?>)programs).get(index)));if(ctx.champion!=null&&base.position!=ctx.champion.position)return null;if(source.equals("MATRIX:FORWARD_REASONING")&&(cell(m,index,0)!=1||cell(m,index,1)<.8||cell(m,index,2)<.9))return null;
  Map<String,Object> contradiction=frames.get("MATRIX:CONTRADICTION"),invariance=frames.get("MATRIX:INVARIANCE"),reverse=frames.get("MATRIX:REVERSE_REASONING");int at=contradiction==null?-1:axis(contradiction,"rows").indexOf(base.policyHash());if(at>=0&&(cell(contradiction,at,0)!=0||cell(contradiction,at,2)>0))return null;int transform=invariance==null?-1:axis(invariance,"rows").indexOf(base.policyHash());if(transform>=0&&(cell(invariance,transform,0)<1-1e-12||cell(invariance,transform,1)<1-1e-12))return null;if(reverse==null||!Integer.valueOf(base.position).equals(details(reverse).get("targetPosition") instanceof Number?((Number)details(reverse).get("targetPosition")).intValue():null))return null;int src=((Number)details(reverse).get("sourcePosition")).intValue();double nonuniform=0;for(int y=0;y<10;y++)for(int x=0;x<10;x++)if(support(reverse,y,x)>=20){double value=cell(reverse,y,x);if(Double.isFinite(value))nonuniform+=Math.abs(value-.1);}if(nonuniform<=.1)return null;
  PolicyAstR27.Node ast=PolicyAstR27.op("mix",.5,PolicyAstR27.op("zscore",base.ast),PolicyAstR27.op("zscore",PolicyAstR27.leaf("crosscond",src)));PolicySpecR27 child=new PolicySpecR27(ast,base.position,base.rule,base.threshold,base.rate,1,true,base.lr,base.forget,IdeaFamilyR27.meta("I10","RESEARCH_PREMISE_HYPOTHESIS",ctx.generation,r.state,"Executable premise/reverse-association hypothesis; research screening only, independent confirmation required",base.policyHash()));if(!FailureProfileR30.legal(child)||ast.depth()>ctx.maxDepth)return null;use(source);use("MATRIX:REVERSE_REASONING");if(at>=0)use("MATRIX:CONTRADICTION");if(transform>=0)use("MATRIX:INVARIANCE");return annotate(child);}
 public PolicySpecR27 calibrationHypothesis(PolicySpecR27 base,IdeaFamilyR27.Context ctx,StatsR27.SplitMix r){Map<String,Object> feedback=frames.get("MATRIX:FEEDBACK"),error=frames.get("MATRIX:STUDENT_ERROR");if(feedback==null||error==null||r.chance(.25)||!base.policyHash().equals(feedback.get("policyHash"))||!base.policyHash().equals(error.get("policyHash"))||support(error,0,2)<200||SetIntersectionPolicyR30.exact(base))return null;Object means=details(feedback).get("confidenceBinMeanProbability");if(!(means instanceof List))return null;double difference=0;int eligible=0;for(int bin=0;bin<3;bin++)if(support(feedback,bin,0)>=200&&((List<?>)means).get(bin) instanceof Number){double observed=cell(feedback,bin,0),predicted=((Number)((List<?>)means).get(bin)).doubleValue();difference+=predicted-observed;eligible++;}if(eligible==0||Math.abs(difference/eligible)<.05)return null;double fitted=ctx.evaluation==null?base.temperature:ctx.evaluation.temperature(base),temperature=Math.max(.05,Math.min(20,fitted*(difference>0?1.5:2.0/3)));PolicySpecR27 child=new PolicySpecR27(base.ast,base.position,base.rule,base.threshold,base.rate,temperature,false,base.lr,base.forget,IdeaFamilyR27.meta("I13","RESEARCH_TEMPERATURE",ctx.generation,r.state,"SELECT-only frozen-readout hypothesis from actual confidence error; no formal calibrator replaced",base.policyHash()));use("MATRIX:FEEDBACK");use("MATRIX:STUDENT_ERROR");return annotate(child);}
 public PolicySpecR27 residualHypothesis(PolicySpecR27 base,IdeaFamilyR27.Context ctx,StatsR27.SplitMix r){Map<String,Object> residual=frames.get("MATRIX:RESIDUAL_MECHANISM");if(residual==null||r.chance(.25)||!base.policyHash().equals(residual.get("policyHash"))||SetIntersectionPolicyR30.exact(base))return null;double largest=0;for(int bin=0;bin<3;bin++)for(int k=0;k<10;k++)if(support(residual,bin,k)>=200&&Double.isFinite(cell(residual,bin,k)))largest=Math.max(largest,Math.abs(cell(residual,bin,k)));if(largest<.05)return null;PolicyAstR27.Node ast=PolicyAstR27.op("mix",.5,PolicyAstR27.op("zscore",base.ast),PolicyAstR27.op("zscore",PolicyAstR27.leaf("freq",base.position,32)));PolicySpecR27 child=base.withAst(ast,IdeaFamilyR27.meta("I10","RESEARCH_RESIDUAL_SMOOTHING",ctx.generation,r.state,"Observed class residual motivates a refutable causal-frequency smoothing hypothesis; no claimed gain",base.policyHash()));if(!FailureProfileR30.legal(child)||ast.depth()>ctx.maxDepth)return null;use("MATRIX:RESIDUAL_MECHANISM");return annotate(child);}
