 /** Ablation: the same context without one source run (its frames are invisible), to measure that run's influence. */
 public ResearchContextR30R1 withoutSourceRunR31(String run){ResearchContextR30R1 copy=new ResearchContextR30R1(datasetHash,revision);for(Map.Entry<String,Map<String,Object>> e:frames.entrySet())if(!run.equals(runs.get(e.getKey()))){copy.frames.put(e.getKey(),e.getValue());if(runs.containsKey(e.getKey()))copy.runs.put(e.getKey(),runs.get(e.getKey()));}return copy;}
